    _fastcmd55 = _read(_live_path(_flow_home(), "commands/fast-dev-flow.md")) or ""
    _disc55 = _v55_fastgates(_fastcmd55)
    _cut55 = re.sub(r"(?ms)^### Gate$.*?(?=^## Phase B)", "", _fastcmd55)
    _add55 = _fastcmd55.replace(
        "## Phase C", "### Security gate\n- **If `state.json` declares `guided: true`, "
        + _V55_GATEMARK + " and takes four further steps.**\n\n## Phase C", 1)
    _owed55 = {
        "fast": _v55_owed("fast", None),
        "core": _v55_owed("core", ["P0", "P1", "P3"]),
        "nostations": _v55_owed("core", []),
        "nomode": _v55_owed(None, ["P1"]),
    }
    good = bool(_disc55 == _V55_FAST_GATES
                and _v55_fastgates(_cut55) != _V55_FAST_GATES
                and _v55_fastgates(_add55) != _V55_FAST_GATES
                and len(_v55_fastgates(_cut55)) == len(_V55_FAST_GATES) - 1
                and len(_v55_fastgates(_add55)) == len(_V55_FAST_GATES) + 1
                and _owed55["fast"] == (list(_V55_FAST_GATES), None)
                and _owed55["core"] == (["P0", "P1", "P3"], None)
                and _owed55["nostations"][0] == []
                and "stations_active" in _owed55["nostations"][1]
                and _owed55["nomode"][0] == [] and "mode" in _owed55["nomode"][1]
                and [_s55 for _s55, _m55 in _run55(guided=True, stations_active=["P1"])]
                == [NOTICE]
                and [_s55 for _s55, _m55 in _run55(mode="core", guided=True)] == [NOTICE])
    ok &= good
    print(f"  V55 {'GATES-derive':<32} expected the owed set to come from the MODE and never "
          f"from a list beside the loop — `stations_active` verbatim in `core`/`full`, "
          f"and in `fast` the declared tuple {_V55_FAST_GATES} equal BOTH WAYS to the gates "
          f"`/fast-dev-flow` publishes, DISCOVERED from the sites carrying the guided pointer "
          f"— with the Phase A gate DELETED and a FOURTH gate ADDED each shown to move "
          f"it, which the phase-heading proxy this replaces could not see · got "
          f"{_disc55} · cut {_v55_fastgates(_cut55)} · add "
          f"{_v55_fastgates(_add55)} · {'ok' if good else 'FAIL'}")

    # (c) ONLY A REACHED GATE IS ACCUSED, AND THE MARKER THAT DECIDED IT IS PRINTED. This is
    # the `C-53` fold the independent review forced: the first cut charged a batch at its
    # FIRST gate for all of them. `fast` reads the batch record, `core`/`full` read
    # `current_station`, and the state where neither can be read is reported rather than
    # guessed. THE CLOSING GATE IS NEVER ACCUSED, which is a loss and is printed as one.
    _first55 = _run55(**_GATED55)                       # no packet: nothing is behind it yet
    _midway55 = _run55(packets=1, **_GATED55)           # Phase B open, A + increment behind
    _midok55 = _run55(packets=1, decisions_log=_FULL55[:2], **_GATED55)
    _coreP0 = _run55(current_station="P0", **_CORE55)
    _coreP4 = _run55(current_station="P4", **_CORE55)
    _corenone = _run55(**_CORE55)
    _sev = lambda _o: [_s55 for _s55, _m55 in _o]
    # AND THE `fast` MARKER READS THE DECLARED HOME, which the first cut of it did not: it
    # counted `_v27_packets` -- hard-coded `03-increments/` -- and PRINTED that it had read
    # `artifact_homes.increments`, so a batch declaring another home had Phase A's gate and
    # the per-increment gate silently EXCUSED. Driven both ways: the packet in the declared
    # home is found, and one in the default home a declaration has moved away from is not.
    _HOME55 = dict(_GATED55, artifact_homes={"increments": "repo:docs/inc/"})
    with tempfile.TemporaryDirectory() as _d55:
        _mk55(_d55, **_HOME55)
        os.makedirs(os.path.join(_d55, "docs", "inc"))
        with open(os.path.join(_d55, "docs", "inc", "increment-1.md"), "w",
                  encoding="utf-8") as _f55:
            _f55.write("x")
        _declared55 = [(_f55.sev, _f55.msg) for _f55 in reg["V55"](_d55, _artifacts(_d55))]
    _elsewhere55 = _run55(packets=1, **_HOME55)
    good = bool(_sev(_first55) == [SKIP, SKIP, SKIP, SKIP]
                and "no `increment-NNN.md` stands under" in _first55[0][1]
                and "`A`, `increment`, `C`" in _first55[1][1]
                and _sev(_midway55)[0] == NOTICE
                and "`A`, `increment`" in _midway55[0][1]
                and "1 increment packet(s) stand under" in _midway55[0][1]
                and "03-increments" in _midway55[0][1]
                and "`C`" in _midway55[1][1] and "CLOSING GATE" in _midway55[1][1]
                and _sev(_midok55) == [SKIP, SKIP, SKIP, SKIP]
                and _sev(_coreP0) == [SKIP, SKIP, SKIP, SKIP]
                and _sev(_coreP4)[0] == NOTICE
                and "`P0`, `P1`, `P3`" in _coreP4[0][1]
                and "current_station: P4" in _coreP4[0][1]
                and _sev(_corenone) == [SKIP, SKIP, SKIP]
                and "no `current_station`" in _corenone[0][1]
                and "NO GATE WAS JUDGED" in _corenone[0][1]
                and "This is not a pass" in _corenone[0][1]
                and _sev(_declared55)[0] == NOTICE and "docs/inc" in _declared55[0][1]
                and _sev(_elsewhere55)[0] == SKIP
                and "no `increment-NNN.md` stands under `docs/inc`" in _elsewhere55[0][1])
    ok &= good
    print(f"  V55 {'REACHED-gates-only':<32} expected a guided batch at its FIRST gate to "
          f"accuse NOTHING and say why, the same batch with a packet on disk to name `A` and "
          f"`increment` and to excuse the CLOSING gate by name, a `core` batch at `P0` to "
          f"accuse nothing and at `P4` to name the four stations behind it, and a `core` "
          f"state with no `current_station` to report that it could not tell — the "
          f"accusation-at-the-first-gate the independent review measured on the seeded "
          f"scaffold — and the `fast` marker to read the home the batch DECLARES, "
          f"driven both ways against a non-default `artifact_homes.increments` · got "
          f"{_shown(set(_sev(_first55)))} → {_shown(set(_sev(_midway55)))} → "
          f"{_shown(set(_sev(_midok55)))} · declared-home "
          f"{_shown(set(_sev(_declared55)))} · {'ok' if good else 'FAIL'}")

    # (d) THE FINDING NAMES THE GATE, AND GOES GREEN WHEN IT IS RECORDED -- the whole rule in
    # one arm, over a batch whose gates are all behind it.
    _partial55 = _run55(packets=2, decisions_log=[_FULL55[0]], **_GATED55)
    _whole55 = _run55(packets=2, decisions_log=_FULL55, **_GATED55)
    _pmsg55 = [_m55 for _s55, _m55 in _partial55 if _s55 == NOTICE]
    good = bool(len(_pmsg55) == 1 and "`increment`" in _pmsg55[0]
                and "1 of the 2 gate(s)" in _pmsg55[0]
                and "`A`" not in _pmsg55[0]
                and _sev(_whole55) == [SKIP, SKIP, SKIP, SKIP]
                and "all 2 gate(s)" in _whole55[0][1])
    ok &= good
    print(f"  V55 {'MISSING-names-the-gate':<32} expected a guided `fast` batch missing its "
          f"per-increment gate to raise ONE NOTICE naming `increment` and not the gate it DID "
          f"record, and the same batch with that entry written to fall silent · got "
          f"{_shown(set(_sev(_partial55)))} → {_shown(set(_sev(_whole55)))} · "
          f"{'ok' if good else 'FAIL'}")

    # (e) BOTH HALVES OF A GUIDED ENTRY ARE READ, which is `C-58` for the flag the adapter
    # tells the agent to write. An entry with the flag and no gate name records that something
    # was approved and not what; an entry with a gate name and no flag is an ORDINARY station
    # decision -- every `core` batch on disk is full of them -- so it is not counted and not
    # complained about, and the difference between the two is the arm.
    _noname55 = _run55(packets=1, decisions_log=[{"guided": True, "decision": "ok"}],
                       **_GATED55)
    _noflag55 = _run55(packets=1, decisions_log=[{"gate": "A", "decision": "ok"}], **_GATED55)
    _mixed55 = _run55(packets=1, decisions_log=_FULL55[:2] + [{"guided": True}], **_GATED55)
    good = bool(_sev(_noname55)[0] == NOTICE and _sev(_noname55)[2] == NOTICE
                and "2 of the 2 gate(s)" in _noname55[0][1]
                and "name no gate" in _noname55[2][1]
                and _sev(_noflag55)[0] == NOTICE and _sev(_noflag55)[2] == SKIP
                and "2 of the 2 gate(s)" in _noflag55[0][1]
                and "(0 entry/entries)" in _noflag55[2][1]
                and _sev(_mixed55)[0] == SKIP and _sev(_mixed55)[2] == NOTICE
                and "1 `decisions_log` entry/entries" in _mixed55[2][1])
    ok &= good
    print(f"  V55 {'ENTRY-both-halves-read':<32} expected `guided: true` with no gate name to "
          f"raise the shape NOTICE and satisfy no gate, a gate name with no `guided` flag to "
          f"satisfy no gate and raise NOTHING about its shape (it is an ordinary station "
          f"decision), and a complete ledger carrying one unnamed guided entry to pass the "
          f"coverage and fail the shape · got "
          f"{_shown(set(_sev(_noname55)))}/{_shown(set(_sev(_noflag55)))}/"
          f"{_shown(set(_sev(_mixed55)))} · {'ok' if good else 'FAIL'}")

    # (f) THE PER-INCREMENT GATE IS OWED ONCE AND TAKEN N TIMES, so the match is a STEM test
    # and the separator is what makes it one. A prefix test would let `increments` answer
    # `increment`, and an equality test would refuse `increment-2`, which is the only spelling
    # a batch with two increments can write.
    _stem55 = [(_v55_matches("increment", {"increment-2"}), True),
               (_v55_matches("increment", {"INCREMENT-11"}), True),
               (_v55_matches("increment", {"increment"}), True),
               (_v55_matches("increment", {"increments"}), False),
               (_v55_matches("increment", {"incrementalism-1"}), False),
               (_v55_matches("increment", {"inc"}), False),
               (_v55_matches("P1", {"P11"}), False),
               (_v55_matches("P1", {"P1"}), True)]
    good = all(_got55 == _want55 for _got55, _want55 in _stem55)
    ok &= good
    print(f"  V55 {'STEM-not-prefix':<32} expected `increment-2` and `INCREMENT-11` to answer "
          f"`increment` and `increments`, `incrementalism-1` and `inc` not to — and `P11` "
          f"never to answer `P1`, which is the same defect at a station id · got "
          f"{sum(1 for _g55, _w55 in _stem55 if _g55 == _w55)} of {len(_stem55)} · "
          f"{'ok' if good else 'FAIL'}")

    # (g) THE FADE-OUT LINE SAYS WHAT IT MEASURES. The first cut printed `streak: 1 of 3
    # consecutive batch(es) CLOSED WITH 0 GATE FINDINGS` on a batch that was neither closed
    # nor finding-free -- the independent review measured it on the staged toy at a run
    # reporting 2 BLOCK and 2 NOTICE -- and `SKILL.md` tells the operator to turn `guided` off
    # on that figure. What is armed is that the token tracks THIS batch's ledger, that no
    # count of closed batches is claimed, and that both halves of the scope are printed.
    _fade55 = [_m55 for _s55, _m55 in _whole55 if "fade-out" in _m55.lower()]
    _fade0 = [_m55 for _s55, _m55 in _partial55 if "fade-out" in _m55.lower()]
    _fadeun55 = [_m55 for _s55, _m55 in _corenone if "fade-out" in _m55.lower()]
    _fadeshape55 = [_m55 for _s55, _m55 in _mixed55 if "fade-out" in _m55.lower()]
    good = bool(len(_fade55) == 1 and len(_fade0) == 1
                and "ledger is COMPLETE" in _fade55[0]
                and "ledger is INCOMPLETE" in _fade0[0]
                # THE WORD IS THE RULE'S OWN VERDICT over EVERY finding it raised, which the
                # first cut derived from `missing` alone: an unnamed-entry NOTICE printed
                # COMPLETE, and so did the state where `missing` is empty BY CONSTRUCTION.
                and "ledger is UNDECIDABLE" in _fadeun55[0]
                and "ledger is INCOMPLETE" in _fadeshape55[0]
                and "never a count of them" in _fade55[0]
                and not re.search(r"\d+ of \d+ consecutive", _fade55[0])
                and "single-slot" in _fade55[0] and "nothing here edits state" in _fade55[0]
                and "in `fast` the owed set is a constant and it could be" in _fade55[0]
                and not [_m55 for _s55, _m55 in _na55["false"] if "fade-out" in _m55.lower()])
    ok &= good
    print(f"  V55 {'LEDGER-says-what-it-measures':<32} expected the fade-out line to report "
          f"THIS batch's ledger COMPLETE/INCOMPLETE rather than a streak of closed batches "
          f"it cannot see, to claim no `N of {_V55_STREAK}` count at all, and to print BOTH "
          f"halves of its scope — the single-slot record in `core`/`full` and the "
          f"rule's own scope in `fast`, where the owed set is a constant and the coverage "
          f"WOULD be recomputable — with the word derived from EVERY finding the rule "
          f"raised, so an unnamed-entry NOTICE reads INCOMPLETE and the undecidable state "
          f"reads UNDECIDABLE rather than borrowing a pass · got "
          f"{len(_fade55)}/{len(_fade0)}/{len(_fadeun55)}/{len(_fadeshape55)} · "
          f"{'ok' if good else 'FAIL'}")

    # (h) THE RULE THAT ASKS A BATCH TO RECORD ITS GATES WRITES NOTHING ITSELF, which is the
    # fade-out's whole argument: an automatic flip would be a rule editing the state it
    # judges. Measured by bytes and by the tree, not asserted from the source.
    with tempfile.TemporaryDirectory() as _d55:
        _sp55 = _mk55(_d55, decisions_log=_FULL55, **_GATED55)
        _mkpkt55(_d55, _GATED55["batch_id"], 1)
        _before55 = (_read(_sp55), sorted(os.listdir(os.path.join(_d55, ".dev-flow"))))
        reg["V55"](_d55, _artifacts(_d55))
        reg["V55"](_d55, _artifacts(_d55))
        _after55 = (_read(_sp55), sorted(os.listdir(os.path.join(_d55, ".dev-flow"))))
    good = bool(_before55 == _after55 and "guided" in (_before55[0] or ""))
    ok &= good
    print(f"  V55 {'NEVER-EDITS-STATE':<32} expected two runs over the same batch to leave "
          f"`state.json` byte-identical and mint no file beside it — the fade-out is the "
          f"operator's act, and a rule that flipped the key would be writing the thing it "
          f"judges · got {'unchanged' if good else 'CHANGED'} · "
          f"{'ok' if good else 'FAIL'}")

    # (i) SEVERITY, OVER EVERY STATE THESE ARMS DRIVE. `guided` exists on no batch on disk, so
    # a BLOCK would refuse every gate of every batch written before the key was minted
    # (`C-53`) -- which is the measured argument, and this is the arm that holds it.
    _sev55 = set()
    for _pk55, _st55 in ((0, {}), (0, dict(mode="fast")), (0, dict(mode="fast", guided=False)),
                         (0, dict(guided=True)), (0, dict(mode="core", guided=True)),
                         (0, _GATED55), (1, _GATED55),
                         (1, dict(decisions_log=_FULL55, **_GATED55)),
                         (1, dict(decisions_log=[{"guided": True}], **_GATED55)),
                         (0, dict(current_station="P4", **_CORE55))):
        _sev55 |= {_s55 for _s55, _m55 in _run55(packets=_pk55, **_st55)}
    good = _sev55 == {SKIP, NOTICE}
    ok &= good
    print(f"  V55 {'SEVERITY-set':<32} expected the severity SET over every state these arms "
          f"drive to be exactly {{SKIP, NOTICE}} — BLOCK is unreachable, which is what "
          f"the NOTICE-only bucket of §Severity claims · got {_shown(_sev55)} · "
          f"{'ok' if good else 'FAIL'}")

    # (j) PASS != NOOP, PER OBLIGATION. Four obligations owe four pass sentences, and a rule
    # whose pass is a silence is a rule nobody can tell from one that never ran.
    _all55 = []
    for _pk55, _st55 in ((0, {}), (0, dict(mode="fast", guided=False)),
                         (0, dict(mode="fast", guided="true")), (0, dict(guided=True)),
                         (0, dict(mode="core", guided=True)), (0, _GATED55), (1, _GATED55),
                         (1, dict(decisions_log=_FULL55, **_GATED55)),
                         (1, dict(decisions_log=[{"guided": True}], **_GATED55)),
                         (0, dict(current_station="P0", **_CORE55)),
                         (0, dict(current_station="P4", **_CORE55)), (0, _CORE55)):
        _all55 += [_m55 for _s55, _m55 in _run55(packets=_pk55, **_st55)]
    _v27msgs55 = set()
    for _mode55 in ("fast", "core"):
        _v27msgs55 |= set(_m55 for _s55, _w55, _m55
                          in _v27_outcome(None, set(), None, "no commit", mode=_mode55))
    good = bool(len(set(_all55)) == 22 and not (set(_all55) & _v27msgs55)
                and all(_w55 == _V55_WHERE for _s55, _w55, _m55
                        in _v55_outcome(True, "fast", list(_V55_FAST_GATES), _FULL55,
                                        ["A", "increment"], "a marker")))
    ok &= good
    print(f"  V55 {'PASS!=NOOP':<32} expected every reachable state to carry a TYPED sentence "
          f"— {len(set(_all55))} distinct over 12 state(s), four obligations each with "
          f"its own pass — sharing none with `V27`'s ledger sentences, which read the "
          f"same key for a different question · got {len(set(_all55))} distinct · "
          f"{'ok' if good else 'FAIL'}")

    # (k) THE SEED'S DIRECTION IS READ, not assumed. `guided` is the one key whose VALUE is a
    # measurement of the project (has it a batch directory yet?), so a seed that wrote the
    # same literal both ways would ship a flow that guides nobody or guides forever, and every
    # arm above would stay green: they all build their own state. The predicate is shown
    # refusing a flipped copy of the very sentence it reads.
    _init55 = _read(_live_path(_flow_home(), "commands/dev-flow-init.md")) or ""
    _seeds55 = [_x55 for _x55 in re.findall(r"```json\n(.*?)```", _init55, re.S)
                if '"guided"' in _x55]

    def _seedrule55(text):
        """Does the command say `true` on a FIRST batch and `false` after it? PURE."""
        return bool(re.search(r"Write `true` when `\.dev-flow/` holds \*\*no batch directory "
                              r"yet\*\*[^.]*?and `false` on every batch after it", text or "",
                              re.S))

    good = bool(len(_seeds55) == 2
                and all(re.search(r'"guided":\s*true', _x55) for _x55 in _seeds55)
                and _seedrule55(_init55)
                and not _seedrule55(_init55.replace("Write `true` when", "Write `false` when"))
                and not _seedrule55(_init55.replace("and `false` on every batch after it",
                                                    "and `true` on every batch after it"))
                and "`V55` is the reader" in _init55)
    ok &= good
    print(f"  V55 {'SEED-first-batch-is-guided':<32} expected BOTH `state.json` seeds "
          f"`/dev-flow-init` publishes to carry `guided: true` and the seeding bullet to say "
          f"`true` on a project's FIRST batch and `false` after it — with the predicate "
          f"shown refusing each half flipped, because a seed that wrote one literal both ways "
          f"passes every arm that builds its own state · got {len(_seeds55)} seed(s) "
          f"· {'ok' if good else 'FAIL'}")

    # (l) THE GATE IS STATED ONCE, IN THE ADAPTER, AND EVERY OTHER FILE POINTS. Both halves
    # are armed, and BOTH were wrong in the first cut: the section predicate greped only
    # literals living in step 4 and below, so steps 1-3 could be replaced or inverted with the
    # arm green (the independent review ran both), and the `C-50` half asked only that no
    # command carried a NUMBERED BOLD step while all four steps stood spelled out, four times
    # over, inside the sentence claiming there was no restatement. Each step now owns a
    # literal shown RED when that step ALONE is rewritten, and the anti-restatement half is a
    # CENSUS over every `.md` the manifest declares.
    _skill55 = _read(_live_path(_flow_home(), "dev-flow/SKILL.md")) or ""
    _sec55 = "".join(re.findall(r"(?ms)^## Guided first run$(.*?)(?=^## )", _skill55)[:1])
    _AGAIN55 = "run the gate again now; it reads the batch this time"
    _WORD55 = {1: "one", 2: "two", 3: "three", 4: "four"}[_V55_STREAK]
    # ONE LITERAL PER STEP, IN STEP ORDER -- the claim each step makes, not its number.
    _STEP55 = ("reader's-map row", "exact next command to run", "Wait for explicit approval",
               "`gate: <the gate's name>`")

    def _guided55(text):
        """Every claim the adapter's section owes. PURE, so a counterfactual can be fed it."""
        return (len(re.findall(r"(?m)^\d\. \*\*", text or "")) == len(_STEP55)
                and all(_st55 in (text or "") for _st55 in _STEP55)
                and _AGAIN55 in (text or "")
                and (_WORD55 + " consecutive batches closed with 0 gate findings")
                in (text or "")
                # THE PAGE MUST DESCRIBE THE RULE THAT SHIPPED, not the one that was
                # proposed. The first cut of this section said `V55` PRINTS THE CURRENT
                # STREAK and gave one half of its scope, and the H1 fold changed the rule
                # without changing the page -- invisible, because the arm read neither
                # sentence. Both claims are literals now, and so is the count it must NOT
                # make.
                # WHITESPACE-NORMALISED, because a required literal coupled to a wrap
                # column turns a cosmetic reflow into a RED selftest that reads as a content
                # defect -- the second review's `M4`.
                and "speaks for exactly ONE of those three and it counts nothing"
                in " ".join((text or "").split())
                and "The operator counts the two" in (text or "")
                and "prints the current" not in (text or "")
                and "`guided: true`" in (text or "")
                and "No rule flips the key" in (text or ""))

    _fullcmd55 = _read(_live_path(_flow_home(), "commands/dev-flow.md")) or ""
    _points55 = tuple(_c55.count("§*Guided first run*")
                      for _c55 in (_fastcmd55, _fullcmd55))
    # THE POPULATION IS WALKED, never listed beside the loop: every `.md` the manifest
    # declares is a file a reader can open, and a fifth copy of a step in any of them is what
    # this looks for.
    _stepsites55 = {_rel55 for _rel55 in (_canon(_flow_home()) or {})
                    if _rel55.endswith(".md")
                    and any(_ph55.lower() in (_read(_live_path(_flow_home(), _rel55))
                                              or "").lower() for _ph55 in _STEP55)}
    good = bool(_sec55 and _guided55(_sec55)
                and not _guided55(_sec55.replace(_AGAIN55, "continue"))
                and not _guided55(re.sub(r"(?s)\*\*Turning it off is MEASURED.*", "", _sec55))
                and all(not _guided55(_sec55.replace(_st55, "do something else"))
                        for _st55 in _STEP55)
                and all(_n55 >= 1 for _n55 in _points55)
                # THE ONE SENTENCE WRITTEN TWICE ON PURPOSE, and both copies are required.
                # The finding was that the instruction was missing AT THE GATE, so a pointer
                # in the fast command would reproduce it; the adapter declares the exception
                # and this conjunct is what keeps the two from diverging.
                and _AGAIN55 in _fastcmd55.lower()
                and "writes TWICE on purpose" in _sec55
                and _stepsites55 == {"dev-flow/SKILL.md"})
    ok &= good
    print(f"  V55 {'SKILL-states-the-gate':<32} expected `SKILL.md` §*Guided first run* to "
          f"carry all {len(_STEP55)} steps BY THEIR OWN CLAIM — each shown RED when that "
          f"step alone is rewritten — plus the close sentence *{_AGAIN55}* and the "
          f"{_WORD55}-batch fade-out, both shown RED when removed, and the "
          f"{len(_STEP55)} step phrases to stand in the ADAPTER ALONE across every `.md` the "
          f"manifest declares, with both commands POINTING {_points55} and the close "
          f"sentence standing in BOTH its declared homes · got "
          f"{_shown(_stepsites55)} · {'ok' if good else 'FAIL'}")

    # ---- rev71. THE DOCUMENT→RULES MAP, DISCOVERED FROM THE SOURCE AND COMPARED BOTH WAYS.
    #
    # THE POPULATION FIGURES THIS REV PUBLISHES ARE NOT ARMED HERE, AND THAT IS DELIBERATE.
    # They were measured over `the record/.dev-flow` — a PROJECT tree, on one machine, outside the
    # manifest and outside `V7`. An arm that reads it by absolute path is verbatim the control
    # this same rev mints: `C-60`, *the harness that proves a check must not resolve its inputs
    # through a path the check does not own* — and this flow has already paid for it twice
    # (rev65's ambient-git-root arm, rev67's `DEVFLOW_HOME` pop). Such an arm passes here and
    # is a hard RED on any other checkout, which is the direction nobody checks. The figures
    # live in the rule's own comment block WITH THEIR DATE AND THEIR CORPUS, the way every
    # other measured figure in this file does.
    #
    # WHAT *IS* ARMED IS THE PROPERTY THIS FILE OWNS: which rules read which document. The map
    # is DISCOVERED by walking every registered rule for its `_v65_document(...)` call and
    # reading the document constant it passes — never a list typed beside the loop, which is
    # `C-50`'s second inventory and the defect this file has now recorded six times. Compared
    # BOTH WAYS: a rule reading `05-close.md` that never joined `_V71_RULES` reddens, and a
    # member of `_V71_RULES` that quietly starts reading another document reddens too.
    # rev83 JOINS THE THIRD FAMILY RATHER THAN OPENING A FOURTH, because the family is the
    # DOCUMENT and not the revision: `V54` reads `05-close.md`, so it belongs where `V50` and
    # `V51` are. The union is written as a union of DECLARED tuples, never as a hand list --
    # the discovered side would agree with a hand list just as happily.
    _DOC_FAMILY71 = {"_V65_DOC": {_r for _r, _l, _i in _V65_RULES},
                     "_V70_DOC": {_r for _r, _l, _i in _V70_RULES},
                     "_V71_DOC": ({_r for _r, _l, _i in _V71_RULES}
                                  | {_r for _r, _l, _i in _V83_RULES})}
    _fnname71 = {_fn.__name__: _rid for _rid, _fn in CHECKS}
    _found71 = {}
    for _n in ast.walk(ast.parse(_read(os.path.abspath(__file__)) or "")):
        if not isinstance(_n, ast.FunctionDef) or _n.name not in _fnname71:
            continue
        for _c in ast.walk(_n):
            if isinstance(_c, ast.Call) and getattr(_c.func, "id", "") == "_v65_document":
                # NO POSITIONAL DOCUMENT ARGUMENT MEANS THE DEFAULT, which is `_V65_DOC` — the
                # rev69 pair's whole relationship to this core, and a walk that only read
                # explicit arguments would report them as reading nothing at all.
                _d71 = (ast.unparse(_c.args[1]) if len(_c.args) > 1
                        else next((ast.unparse(_k.value) for _k in _c.keywords
                                   if _k.arg == "doc_name"), "_V65_DOC"))
                _found71.setdefault(_d71, set()).add(_fnname71[_n.name])
    good = _found71 == _DOC_FAMILY71
    ok &= good
    print(f"  V50 {'DOC-FAMILIES-both-ways':<32} expected the document→rules map DISCOVERED "
          f"from {len(_fnname71)} registered rules' own `_v65_document` calls to equal the "
          f"{len(_DOC_FAMILY71)} declared families exactly — a rule reading `{_V71_DOC}` that "
          f"never joined the family, and a family member that drifts to another document, are "
          f"the same defect from opposite ends · got "
          f"{' · '.join('%s=%s' % (_k, _shown(_found71[_k])) for _k in sorted(_found71))} · "
          f"{'ok' if good else 'FAIL'}")

    # ---- rev71 (`T10`). A NUMBER IN A HEADING COUNTS THE BLOCK BENEATH IT AND GOT IT WRONG,
    # at every site that stated one, about a contract whose own instruction is *the key is
    # never dropped*.
    #
    # THE AXIS, ENUMERATED BEFORE ANYTHING WAS EDITED, and it is larger than the item that
    # opened it. `T10` reports "12 vs 13" at three sites. Measured over `commands/` and
    # `templates/`, there are exactly TWO yaml metrics fences in the whole flow and THREE prose
    # sites naming a count for them, and the three named FOUR numbers between them, of which
    # NOT ONE agreed with a fence:
    #
    #   close-template.md §5 heading   said `12 keys of core`   · its own fence holds **13**
    #   dev-flow-sync.md  mode branch  said `12 keys`           · the README fence holds **35**
    #   dev-flow.md       mode table   said `12 keys / 31 keys` · the two fences hold 13 / 35
    #
    # So `31` described nothing on disk at all, and the `12` at the sync site was not even
    # about the same POPULATION as the `12` in the close template -- one counts the `core`
    # metrics block, the other the vault README's frontmatter schema. Two populations, one
    # number, both wrong, and the coincidence is why the item read as a single typo.
    #
    # THE RULING, AND WHY IT IS NOT "DERIVE ALL THREE". The sync site claimed a 12-key SUBSET
    # of the 35-key schema and NO FENCE DECLARES THAT SUBSET, so it cannot be derived from
    # anything -- minting a subset fence beside the close block that already holds the
    # extractable set would be `C-50`'s second inventory. That site therefore NAMES NO NUMBER
    # and points at the schema; the two sites that CAN be derived keep their figure and this
    # arm derives it. A count is kept where a fence backs it and dropped where none does.
    def _yamlkeys71(text):
        """The key set of a document's FIRST yaml fence, in order. PURE."""
        _m = re.search(r"```yaml\n(.*?)\n[ \t]*```", text or "", re.S)
        return tuple(re.match(r"^\s*([A-Za-z_][A-Za-z0-9_]*):", _l).group(1)
                     for _l in (_m.group(1).splitlines() if _m else [])
                     if re.match(r"^\s*[A-Za-z_][A-Za-z0-9_]*:", _l))

    _CLOSE71 = "templates/dev-flow/close-template.md"
    _SYNC71 = "commands/dev-flow-sync.md"
    _MODE71 = "commands/dev-flow.md"
    _fence71 = {_p: _yamlkeys71(_read(_live_path(_flow_home(), _p)) or "")
                for _p in (_CLOSE71, _SYNC71)}
    # ONE FENCE PER SITE, ASSERTED -- the review's LOW. `_yamlkeys71` reads the FIRST yaml
    # fence, which is correct today and silently wrong the day either document grows a second:
    # the count would keep describing the first and nothing would say so.
    _nfence71 = {_p: len(re.findall(r"```yaml\n", _read(_live_path(_flow_home(), _p)) or ""))
                 for _p in (_CLOSE71, _SYNC71)}
    # THE EXPECTED VECTOR IS DERIVED FROM THE FENCES, never typed: `close-template.md` names
    # its own block once, `dev-flow.md` names both, and `dev-flow-sync.md` names NEITHER.
    _want71k = {_CLOSE71: [len(_fence71[_CLOSE71])],
                _MODE71: [len(_fence71[_CLOSE71]), len(_fence71[_SYNC71])],
                _SYNC71: []}
    # A FIGURE INSIDE QUOTATION MARKS IS A QUOTATION AND NOT A CLAIM -- rev67's `quoted`
    # bucket, and it is load-bearing here because this rev's own explanatory block QUOTES the
    # wrong figure it replaced. Excusing it silently would let a real fourth site hide behind
    # a pair of quotes, so the quoted set is asserted as an EXACT vector too.
    def _keyclaims71(text):
        _claims, _quoted = [], []
        for _m in re.finditer(r"(\d+)[ -]keys?\b", text or ""):
            _lo = max(0, _m.start() - 90)
            (_quoted if re.search(r"[\"“”]", (text or "")[_lo:_m.start()])
             else _claims).append(int(_m.group(1)))
        return _claims, _quoted
    # THE SITES ARE DISCOVERED, NOT TYPED -- rev71's independent review, MEDIUM (`F3`), and it
    # was right twice over: the first cut kept THREE paths as constants beside the loop, which
    # is `C-50`'s second inventory inside the arm that cites `C-50`, AND the template sentence
    # beside it claimed the census was total (*"a fourth site reddens"*) when a planted fourth
    # site in `commands/fast-dev-flow.md` passed silently. The scan now walks the NORMATIVE
    # corpus and the site set is compared BOTH WAYS.
    #
    # `docs/**` IS A DECLARED, NAMED EXCLUSION AND NOT AN OVERSIGHT. `FLOW-VERSION.md`'s
    # changelog carries several unquoted `N keys` figures -- rev62's *"`state.json` went from
    # 11 keys to 17"*, and this rev's own row reciting the retired `12` -- and those rows are a
    # DATED RECORD OF WHAT WAS BELIEVED, not an instruction to an agent. Rewriting them to
    # satisfy a census would be editing the past to make the present measurable, which is the
    # same reasoning that leaves batch-74's `06-closeout.md` out of `V50`'s population.
    _KEYCORP71 = sorted(
        _rel for _dir in ("commands", "templates/dev-flow")
        for _rel in [(_dir + "/" + _n) for _n in
                     sorted(os.listdir(os.path.join(_flow_home(), _dir)))]
        if _rel.endswith(".md"))
    _got71k, _q71k = {}, {}
    for _p in _KEYCORP71:
        _c71, _qq71 = _keyclaims71(_read(_live_path(_flow_home(), _p)) or "")
        if _c71:
            _got71k[_p] = _c71
        if _qq71:
            _q71k[_p] = _qq71
    good = (_got71k == {_k: _v for _k, _v in _want71k.items() if _v}
            and _q71k == {_CLOSE71: [12]}
            and len(_fence71[_CLOSE71]) == 13 and len(_fence71[_SYNC71]) == 35
            and _keyclaims71("| batch metrics | 12 keys |")[0] == [12]
            and set(_nfence71.values()) == {1}
            and all(_p in _KEYCORP71 for _p in (_CLOSE71, _SYNC71, _MODE71)))
    ok &= good
    print(f"  V51 {'KEYCOUNT-derived':<32} expected the unquoted `N keys` claims DISCOVERED "
          f"across all {len(_KEYCORP71)} normative documents (`commands/` + "
          f"`templates/dev-flow/`, `docs/**` a declared exclusion) to be exactly the sites a "
          f"yaml fence backs, both ways — close {len(_fence71[_CLOSE71])}, sync README "
          f"{len(_fence71[_SYNC71])}, the sync mode-branch naming none because no fence "
          f"declares its subset — with this rev's own QUOTATION of the retired `12` excused as "
          f"quoted, and the scanner shown to SEE a planted claim · got "
          f"{' · '.join('%s=%s' % (_p.split('/')[-1], _got71k[_p]) for _p in sorted(_got71k))}"
          f"{' · quoted ' + ' '.join('%s=%s' % (_p.split('/')[-1], _q71k[_p]) for _p in sorted(_q71k)) if _q71k else ''}"
          f" · {'ok' if good else 'FAIL'}")

    # THE RED PROOF, IN PROCESS AND BOTH WAYS. A derivation nobody has seen move is a constant
    # with extra steps (`C-57`). A planted FOURTEENTH key must change the derived count and
    # break the agreement; a planted `12 keys` at the site this rev just emptied must be
    # DISCOVERED, or the census cannot see a fourth site appear.
    _plant71 = _read(_live_path(_flow_home(), _CLOSE71)) or ""
    _p14 = _yamlkeys71(_plant71.replace("open_items_next: <int>",
                                        "open_items_next: <int>\nzzkey: <int>"))
    _psite = _keyclaims71("| batch metrics | — | 12 keys | 31 keys |")[0]
    good = (len(_p14) == 14 and "zzkey" in _p14 and "zzkey" not in _fence71[_CLOSE71]
            and _p14[:13] == _fence71[_CLOSE71] and _psite == [12, 31])
    ok &= good
    print(f"  V51 {'KEYCOUNT-red-proof':<32} expected a planted 14th key to take the same parse "
          f"to {len(_p14)} with the real 13 unchanged beneath it, and the RETIRED mode-table "
          f"row to be read by the same claim-scanner as {_psite} — a derivation nobody has "
          f"seen move is a constant · {'ok' if good else 'FAIL'}")

    # ---- rev71 (`BRIEF-6` §2.1, `C-47`). A RULE THAT IMPLEMENTS A CONTROL NAMES IT, AND THE
    # NAME RESOLVES. `C-47` was counted an ORPHAN -- 0 citations in commands + templates +
    # validator -- while `V9` has been its only mechanism since rev5 and raises 231 notices on
    # this project's record today. Nothing was missing but the citation, which is why the whole
    # disposition is one tag. What this arm adds is that the tag cannot rot: every `C-NN` named
    # in `_RULE_COVERS` must resolve to a heading the SHIPPED catalog actually carries, by the
    # manifest's own published derivation (`#{1,3} ` and a space, never `#{1,6}`).
    # ⚠ AND THE ARM FOUND TWO ON ITS FIRST RUN, WHICH IS WHY IT IS A CENSUS AND NOT A SPOT
    # CHECK ON `V9`. `V43` cites `C-26` and `V44` cites `C-20`, and NEITHER is a numbered
    # control: both exist in the catalog ONLY as `####` origin-story headings, the depth the
    # manifest's derivation deliberately scores 0 (that is rev60's repair of the `controls:`
    # row, and its third planted probe). So two rules shipped at rev68 naming origins that the
    # flow's own definition of "a control" does not contain.
    #
    # THE DISPOSITION IS A DECLARED EXCLUSION, NOT A WIDENING, and the reason is that the
    # alternative is a ruling this rev has no standing to make. Minting `C-20`/`C-26` as
    # numbered controls is an operator sitting under the project's control-encode rule -- the
    # same rule that keeps `C-61` unminted three sections below. Widening the arm to `#{1,6}`
    # would instead re-adopt the derivation rev60 repaired, and would score an origin story as
    # a control everywhere. So the two are NAMED here with their depth, and the vector is
    # EXACT: a THIRD unresolving tag reddens instead of joining them silently.
    _cat71 = _read(_live_path(_flow_home(), "skills/dev-flow-lessons/SKILL.md")) or ""
    _heads71 = set(re.findall(r"C-\d+", "\n".join(
        re.findall(r"^#{1,3} .*\bC-\d+\b.*$", _cat71, re.M))))
    _deep71 = set(re.findall(r"C-\d+", "\n".join(
        re.findall(r"^#{4,6} .*\bC-\d+\b.*$", _cat71, re.M))))
    _ORIGIN_ONLY71 = {"C-20", "C-26"}
    _tags71 = {_rid: sorted(set(re.findall(r"`(C-\d+)`", _txt)))
               for _rid, _txt in _RULE_COVERS.items() if re.search(r"`C-\d+`", _txt)}
    _ghost71 = sorted({_c for _cs in _tags71.values() for _c in _cs} - _heads71)
    good = (set(_ghost71) == _ORIGIN_ONLY71
            and _ORIGIN_ONLY71 <= _deep71 and not (_ORIGIN_ONLY71 & _heads71)
            and "V9" in _tags71 and _tags71["V9"] == ["C-47"] and "C-47" in _heads71
            and "C-999" not in _heads71
            and sorted(set(re.findall(r"`(C-\d+)`", "cites `C-999` and `C-47`")))
            == ["C-47", "C-999"])
    ok &= good
    print(f"  V9  {'ORIGIN-tags-resolve':<32} expected all {len(_tags71)} origin-tagged rule(s) "
          f"to cite ids the shipped catalog gives a `#{{1,3}}` heading ({len(_heads71)} of "
          f"them), `V9` to name `C-47` — the control it has implemented since rev5 and never "
          f"cited — with EXACTLY {_shown(_ORIGIN_ONLY71)} excused as `####` origin-only "
          f"headings awaiting an operator sitting, and the same extractor to see a planted "
          f"`C-999` · ghosts {_shown(set(_ghost71)) if _ghost71 else '{}'} · "
          f"{'ok' if good else 'FAIL'}")

    # ---- rev77 ("rev E"). V52: `C-49`'s FORWARD-APPLICABILITY TABLE GETS ITS FIRST READER.
    #
    # THE ARMS BELOW ARE BUILT AROUND ONE HAZARD THAT NONE OF THE rev69-rev71 FAMILIES HAD.
    # Every earlier field-keyed rule reads a cell the template leaves EMPTY, so an untouched
    # artifact scores `empty` for free. This template PRE-FILLS the consumer column on all four
    # of its rows -- so a reader keyed on `C-49`'s literal sentence alone PASSES the untouched
    # template, and a battery driving only empty consumers would print `ok` over a rule that
    # certifies the very thing it exists to catch. `TWO-LIMBS-are-not-one` drives exactly that
    # counterfactual against the LIVE shipped template, and it is the arm that would have
    # caught a one-limb first cut.
    _V52_TABLE_FILLED = (
        "| Output of this PDR | Named consumer downstream | Where the consumer will read it |\n"
        "|---|---|---|\n"
        "| design characteristics | the Phase-3 increments | `03-increments/increment-1.md` |\n"
        "| the proposed test cases | layers 0/A/B and the DDR | `04-validation.md` §1 |\n")
    _V52_TABLE_NOCONSUMER = (
        "| Output of this PDR | Named consumer downstream | Where the consumer will read it |\n"
        "|---|---|---|\n"
        "| design characteristics | the Phase-3 increments | `03-increments/increment-1.md` |\n"
        "| a sequence diagram of the old flow |  | `<…>` |\n")
    _V52_DOC = ("# Design proposal — P — Batch B\n\n"
                "## 6 · Something else\n\nprose\n\n"
                "## 7 · Forward-applicability table — **the section that makes this "
                "document honest**\n\n%s\n"
                "- ⚠ Any row whose consumer column is empty: **remove the output.**\n\n"
                "## 8 · Parallelisation plan\n\n| Lane | Agent |\n|---|---|\n| one | a |\n")
    _V52_NOSECTION = ("# Design proposal — P — Batch B\n\n## 6 · Something\n\n"
                      "## 8 · Parallelisation plan\n")
    _V52_REVIEW = ("# Design review record — PDR — Batch B\n\n"
                   "## 7 · Forward-applicability table\n\n| a | b | c |\n|---|---|---|\n"
                   "| x | y | z |\n")

    # THE LIVE SHIPPED TEMPLATE, read from the flow's own home rather than retyped here. A
    # fixture reproducing the template's four rows by hand would go on passing after somebody
    # edited the template, which is the second-inventory defect (`C-50`) inside the very arm
    # that exists to hold the template and its reader together.
    _tpl77 = _read(_live_path(_flow_home(),
                              "templates/dev-flow/design-proposal-template.md")) or ""
    _sec77 = _md_section(_tpl77, _V52_HEADING)
    _rows77 = _v52_rows(_sec77[0]) if _sec77 else None
    good = (bool(_sec77) and bool(_rows77) and len(_rows77) >= 1
            and all(len(r) == 3 for r in _rows77))
    ok &= good
    print(f"  V52 {'TEMPLATE-mints-the-section':<32} expected the SHIPPED "
          f"`design-proposal-template.md` to carry `## {_V52_HEADING}` with at least one "
          f"3-column DATA row — the section this rule is keyed to, read from the live template "
          f"and never retyped; the COUNT is deliberately not pinned, so adding a fifth output "
          f"to the template is a template edit and not a selftest failure · got "
          f"{len(_rows77 or [])} row(s) · {'ok' if good else 'FAIL'}")

    # LIMB TWO AGAINST THE LIVE TEMPLATE. The untouched section must read RED, because that is
    # the state 0 of 949 files in the record have ever left it in.
    _out77 = _v52_outcome("ok", [("PDR-B.md", _rows77)])
    good = (len(_out77) == 1 and _out77[0][0] == NOTICE
            and "NOT ONE says where its consumer will read" in _out77[0][2])
    ok &= good
    print(f"  V52 {'SHIPPED-TEMPLATE-is-unfilled':<32} expected the LIVE template's own §7 to "
          f"raise exactly one NOTICE saying no row names where its consumer reads the output — "
          f"the unfilled state of the whole record · "
          f"{'ok' if good else 'FAIL: ' + repr(_out77)}")

    # AND THE COUNTERFACTUAL THAT MAKES THE ARM ABOVE MEAN SOMETHING. `C-49`'s own sentence is
    # about the CONSUMER column and the template FILLS it, so a rule with only that limb is
    # SILENT on the untouched template. Both halves are driven: the consumer limb finds nothing
    # here (proving it is not what raised the notice above) and catches the planted blank cell
    # (proving it is not dead). Without this pair the first arm passes under a one-limb reader.
    _consumer77 = [r for r in (_rows77 or []) if len(r) < 2 or not _v60_bare(r[1])]
    _blank77 = _v52_outcome("ok", [("PDR-B.md", _v52_rows(_V52_TABLE_NOCONSUMER))])
    good = (not _consumer77
            and any("means DELETE the output" in m for _s, _w, m in _blank77)
            and all(_s == NOTICE for _s, _w, _m in _blank77))
    ok &= good
    print(f"  V52 {'TWO-LIMBS-are-not-one':<32} expected the live template's "
          f"{len(_rows77 or [])} row(s) to fill the CONSUMER column on every one — so a reader "
          f"keyed on `C-49`'s literal sentence alone would PASS the untouched template — while "
          f"the same limb CATCHES a planted blank consumer · consumer-limb hits on the "
          f"template {len(_consumer77)} · {'ok' if good else 'FAIL'}")

    def _mk77(root, docs, stations=("P0", "P1", "PDR", "P3"), batch="2026-08-28-batch-89",
              extra=None):
        """A `.dev-flow/` whose ACTIVE batch stages `docs` under `design/`.

        THE DIRECTORY NAME IS A LITERAL HERE AND `_V52_DIR` EVERYWHERE ELSE, which looks like
        the duplication this file refuses and is the opposite of it. The staging home is the
        CONTRACT `/dev-flow` and `/dev-flow-sync` write against; a fixture that read the
        constant under test would move with it, and `r77-M05` -- one letter on that constant --
        SURVIVED the first battery for exactly that reason, with every arm still green over a
        rule looking in a directory nothing writes to.
        """
        d = os.path.join(root, ".dev-flow", batch, "design")
        os.makedirs(d, exist_ok=True)
        for _name, _body in docs.items():
            with open(os.path.join(d, _name), "w", encoding="utf-8") as fh:
                fh.write(_body)
        _st = {"batch_id": batch, "stations_active": list(stations)}
        _st.update(extra or {})
        with open(os.path.join(root, ".dev-flow", "state.json"), "w", encoding="utf-8") as fh:
            json.dump(_st, fh)

    for _arm77, _docs77, _wsev77, _frag77 in (
            ("PASS-sentence", {"PDR-B.md": _V52_DOC % _V52_TABLE_FILLED}, SKIP,
             "names a consumer on all 2 row(s), 2 of them saying where"),
            ("UNFILLED-finding", {"PDR-B.md": _V52_DOC % (_sec77[0] if _sec77 else "")}, NOTICE,
             "NOT ONE says where its consumer will read"),
            ("EMPTY-CONSUMER-finding", {"PDR-B.md": _V52_DOC % _V52_TABLE_NOCONSUMER}, NOTICE,
             "means DELETE the output"),
            ("NO-SECTION-finding", {"PDR-B.md": _V52_NOSECTION}, NOTICE,
             "carries no `## %s` table" % _V52_HEADING),
            ("NO-TABLE-finding",
             {"PDR-B.md": _V52_DOC % "| a | b | c |\n|---|---|---|\n"}, NOTICE,
             "holds a header and no data row"),
            ("NO-PROPOSAL-finding", {"02-pdr-record.md": _V52_REVIEW}, NOTICE,
             "stages no design proposal")):
        with tempfile.TemporaryDirectory() as _d77:
            _mk77(_d77, _docs77)
            _f77 = [(f.sev, f.where, f.msg) for f in reg["V52"](_d77, _artifacts(_d77))]
        good = (len(_f77) == 1 and _f77[0][0] == _wsev77 and _frag77 in _f77[0][2]
                and _f77[0][1].startswith(_V52_WHERE)
                and all(s != BLOCK for s, _w, _m in _f77))
        ok &= good
        print(f"  V52 {_arm77:<32} expected one {_wsev77} carrying {_frag77[:46]!r} through the "
              f"registered rule, under `{_V52_WHERE}` · "
              f"{'ok' if good else 'FAIL: ' + repr(_f77)}")

    # THE STATION SCOPING, AS A DIFFERENTIAL AND NOT AS AN ASSERTION. `C-53`: a rule that
    # false-fails correct work costs what one that passes wrong work costs. `PDR` is
    # trigger-activated — the ACTIVE batch of the record runs `core` with no `PDR` in
    # `stations_active` — so the SAME tree must be silent without the station and RED with it.
    # A one-sided arm cannot tell a correctly scoped rule from a rule that never fires.
    _scope77 = {}
    for _tag77, _st77 in (("no-PDR", ("P0", "P1", "P3", "P4", "P5")),
                          ("PDR", ("P0", "P1", "PDR", "P3"))):
        with tempfile.TemporaryDirectory() as _d77:
            _mk77(_d77, {"PDR-B.md": _V52_DOC % (_sec77[0] if _sec77 else "")}, stations=_st77)
            _scope77[_tag77] = [(f.sev, f.msg) for f in reg["V52"](_d77, _artifacts(_d77))]
    good = (len(_scope77["no-PDR"]) == 1 and _scope77["no-PDR"][0][0] == SKIP
            and "owes no design proposal" in _scope77["no-PDR"][0][1]
            and len(_scope77["PDR"]) == 1 and _scope77["PDR"][0][0] == NOTICE)
    ok &= good
    print(f"  V52 {'SCOPE-station-differential':<32} expected the SAME unfilled proposal to be "
          f"a `C-53` SKIP when `stations_active` names no `PDR` and a NOTICE when it does — "
          f"the false-fail a mode-keyed rule would charge every `core` batch · "
          f"{'ok' if good else 'FAIL: ' + repr(_scope77)}")

    # rev77's review, HIGH (`F2`). `/dev-flow-init` step 4 seeds this template into `full`
    # UNCONDITIONALLY, and step 3 writes `full` -> `["P0".."P6"]` with no `PDR` until a trigger
