    _cen80 = _census80(_cat66, _ref80)
    _cut80 = _census80("\n".join(_cat66.split("\n")[:-40]), _ref80)
    _cutr80 = _census80(_cat66, "\n".join(_ref80.split("\n")[:-40]))
