        ("machine-directory", "skills/dev-flow/commands/dev-flow.md",
         "cache under AppData/Local/example"),
        ("email-address", "skills/dev-flow/FLOW-VERSION.md",
         "questions to someone@example.org"),
        ("api-key-shape", "skills/dev-flow/templates/req-template.md",
         "deploy token = ghp_ABCDEFGHIJKLMNOPQRSTUVWXYZ012345"),
        ("commit-trailer", "skills/dev-flow/agents/tester.md",
         "Co-Authored-By: Someone <someone@example.org>"),
        ("foreign-env-var", "skills/dev-flow/commands/fast-dev-flow.md",
         "set %BUILDROOT% before running"),
