    _capnumbad67 = tuple(sorted(_r for _r, _v in _capnum67.items() if _v != {"4"}))
    _capnumplant67 = (_CAPNUM67.search("- **\u22649 SOURCE files per increment**").group(1)
                      == "9",
                      _CAPNUM67.search("- **\u22644 SOURCE files per increment**").group(1)
                      == "4",
                      # G4's own counterexample: the `Max` form, which the first cut could not
                      # read at all, in both directions.
                      _CAPNUM67.search("- **Max 4 SOURCE files per increment**").group(1) == "4",
                      _CAPNUM67.search("- **Max 9 SOURCE files per increment**").group(1) == "9")
